import React, { useState, useEffect, useCallback } from 'react';
import './Navbar.css';
import Navigation from './Navigation/Navigation';

const defaultLogo = (
  <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" fill="none" viewBox="0 0 40 40">
    <path fill="var(--theme-color)" d="M20 0c11.046 0 20 8.954 20 20v14a6 6 0 0 1-6 6H21v-8.774c0-2.002.122-4.076 1.172-5.78a10 10 0 0 1 6.904-4.627l.383-.062a.8.8 0 0 0 0-1.514l-.383-.062a10 10 0 0 1-8.257-8.257l-.062-.383a.8.8 0 0 0-1.514 0l-.062.383a9.999 9.999 0 0 1-4.627 6.904C12.85 18.878 10.776 19 8.774 19H.024C.547 8.419 9.29 0 20 0Z"></path>
    <path fill="var(--theme-color)" d="M0 21h8.774c2.002 0 4.076.122 5.78 1.172a10.02 10.02 0 0 1 3.274 3.274C18.878 27.15 19 29.224 19 31.226V40H6a6 6 0 0 1-6-6V21ZM40 2a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z"></path>
  </svg>
);

const defaultOptions = [
  { label: "About Us", action: "" },
  { label: "Results", action: "" },
  { label: "Services", action: "" },
  { label: "Process", action: "" },
  { label: "FAQs", action: "" },
];

const NavBar = ({
  logo = defaultLogo,
  options = defaultOptions,
  ctaLabel = "Book a call",
  ctaAction = "",
  responsiveWidth = 768
}) => {
  const [isMobile, setIsMobile] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isAnimated, setIsAnimated] = useState(false);
  const [visible, setVisible] = useState(true);
  const [prevScrollPos, setPrevScrollPos] = useState(0);
  const [hasScrolled, setHasScrolled] = useState(false);

  const handleResize = useCallback(() => {
    setIsMobile(window.innerWidth <= responsiveWidth);
  }, [responsiveWidth]);

  useEffect(() => {
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [handleResize]);

  useEffect(() => {
    const handleScroll = () => {
      const currentScrollPos = window.scrollY;
      setVisible(prevScrollPos > currentScrollPos || currentScrollPos < 10);
      setHasScrolled(currentScrollPos > 10);
      setPrevScrollPos(currentScrollPos);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [prevScrollPos]);

  useEffect(() => {
    const timer = setTimeout(() => setIsAnimated(true), 100);
    return () => clearTimeout(timer);
  }, []);

  const handleAction = (action) => {
    if (typeof action === 'string') {
      window.location.href = action;
    } else if (typeof action === 'function') {
      action();
    }
    setIsMenuOpen(false);
  };

  return (
    <div className={`nav-container ${isMobile ? 'mobile' : ''} ${!isMobile && isAnimated ? 'animate' : ''} ${visible ? '' : 'hidden'} ${hasScrolled ? 'scrolled' : ''}`}>
      <nav className="nav">
        <div className="nav-content">
          <div className="logo-container">
            {logo}
            <span style={{color:"#ffffff", marginLeft:"10px"}}>Elyse</span>
          </div>
          
          {!isMobile && (
            <div className="desktop-menu">
              <Navigation
                fontSize="var(--font-size)"
                fontColor="var(--text-primary)"
                fontWeight={500}
                horizontalPadding="12px"
                verticalPadding="10px"
                borderRadius="6px"
                gap="8px"
                iconSize="12px"
                backgroundColor="var(--theme-background)"
                hoverBgColor="var(--bg-banner)"
                contentDivWidth="125%"
                showContentBorder={true}
                contentBorderRadius="8px"
                contentBorderColor="var(--border-color)"
                contentTopMargin="28px"
              />
              <button className="cta" onClick={() => handleAction(ctaAction)}>
                {ctaLabel}
              </button>
            </div>
          )}
          
          {isMobile && (
            <div className="mobile-controls">
              <button 
                className={`hamburger ${isMenuOpen ? 'open' : ''}`} 
                onClick={() => setIsMenuOpen(!isMenuOpen)}
              >
                <span></span>
                <span></span>
                <span></span>
              </button>
            </div>
          )}
        </div>
        
        {isMobile && (
          <div className={`mobile-menu-container ${isMenuOpen ? 'open' : ''}`}>
            <div className="mobile-menu">
              {options.map((option, index) => (
                <button 
                  key={index} 
                  onClick={() => handleAction(option.action)}
                  className="option"
                >
                  {option.label}
                </button>
              ))}
              <button className="cta" onClick={() => handleAction(ctaAction)}>
                {ctaLabel}
              </button>
            </div>
          </div>
        )}
      </nav>
    </div>
  );
};

export default NavBar;