import React, { useState, useEffect, useMemo } from "react";
import './MultiAvatars.css';

const generateGradient = (index) => {
  const gradients = [
    'linear-gradient(to right, #eea2a2 0%, #bbc1bf 19%, #57c6e1 42%, #b49fda 79%, #7ac5d8 100%)',
    'linear-gradient(to top, #7028e4 0%, #e5b2ca 100%)',
    'linear-gradient(-60deg, #ff5858 0%, #f09819 100%)',
    'linear-gradient(to top, #3b41c5 0%, #a981bb 49%, #ffc8a9 100%)',
    'linear-gradient(45deg, #ff9a9e 0%, #fad0c4 99%, #fad0c4 100%)',
    'linear-gradient(to right, #ff8177 0%, #ff867a 0%, #ff8c7f 21%, #f99185 52%, #cf556c 78%, #b12a5b 100%)',
    'linear-gradient(120deg, #d4fc79 0%, #96e6a1 100%)',
    'linear-gradient(to right, #43e97b 0%, #38f9d7 100%)',
    'linear-gradient(180deg, #2af598 0%, #009efd 100%)',
    'linear-gradient(to right, #6a11cb 0%, #2575fc 100%)',
  ];
  return gradients[index % gradients.length];
};

const Avatar = React.memo(({ url, index, style, alt }) => {
  const [imageLoaded, setImageLoaded] = useState(false);
  const [imageError, setImageError] = useState(false);

  useEffect(() => {
    const img = new Image();
    img.src = url;
    img.onload = () => setImageLoaded(true);
    img.onerror = () => setImageError(true);
  }, [url]);

  const backgroundStyle = imageLoaded && !imageError
    ? { backgroundImage: `url(${url})`, backgroundSize: "cover", backgroundPosition: "center" }
    : { backgroundImage: generateGradient(index), backgroundSize: "cover", backgroundPosition: "center" };

  return (
    <div
      className="mavtar-icon"
      style={{
        ...style,
        ...backgroundStyle
      }}
      role="img"
      aria-label={alt}
    />
  );
});

const MultiAvatars = React.memo(({
  numPeople = 0,
  className,
  avatarUrls = [],
  avatarSize = "50px",
  avatarBorderWidth = "2px",
  avatarBorderColor = "#ffffff",
  avatarRightShift = "20px",
  showNumbersDiv = true,
  numbersDivBackground = "#000000",
  numbersDivFontColor = "#ffffff",
  numbersDivFontSize = "12px",
  numbersDivFontWeight = 500,
  scaleOnHover = true,
  onNumbersDivClick = () => {},
  ariaLabel = "User avatars"
}) => {
  const containerStyle = useMemo(() => ({
    zIndex: 10,
    display: 'flex',
    alignItems: 'center',
  }), []);

  const avatarStyle = useMemo(() => ({
    height: avatarSize,
    width: avatarSize,
    borderRadius: '9999px',
    borderWidth: avatarBorderWidth,
    borderStyle: 'solid',
    borderColor: avatarBorderColor,
    marginRight: `-${avatarRightShift}`,
    boxSizing: 'content-box',
    zIndex: 0,
    userSelect: "none",
  }), [avatarSize, avatarBorderWidth, avatarBorderColor, avatarRightShift]);

  const numbersDivStyle = useMemo(() => ({
    display: 'flex',
    height: avatarSize,
    width: avatarSize,
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: '9999px',
    borderWidth: avatarBorderWidth,
    borderStyle: 'solid',
    borderColor: numbersDivFontColor,
    backgroundColor: numbersDivBackground,
    textAlign: 'center',
    fontSize: numbersDivFontSize,
    fontWeight: numbersDivFontWeight,
    color: '#ffffff',
    textDecoration: 'none',
    userSelect: "none",
    boxSizing: 'content-box',
    zIndex: avatarUrls.length,
  }), [avatarSize, avatarBorderWidth, numbersDivFontColor, numbersDivBackground, numbersDivFontSize, numbersDivFontWeight, avatarUrls.length]);

  return (
    <div 
      style={containerStyle} 
      className={className}
      role="group"
      aria-label={ariaLabel}
    >
      {avatarUrls.map((url, index) => (
        <Avatar
          key={url}
          url={url}
          index={index}
          style={{...avatarStyle, zIndex: index}}
          alt={`User avatar ${index + 1}`}
        />
      ))}
      {showNumbersDiv && numPeople > 0 && (
        <div
          onClick={onNumbersDivClick}
          className={`${scaleOnHover ? "mavtar-icon" : ""} mav-numbers-div`}
          style={numbersDivStyle}
          role="button"
          aria-label={`${numPeople} more users`}
        >
          +{numPeople}
        </div>
      )}
    </div>
  );
});

export default MultiAvatars;