import React, { useEffect, useState, memo } from 'react';
import './Hero.css';
import MultiAvatars from '../MultiAvatars';
import GlowCard from '../GlowCard';


// Animation timing hook
const useAnimationDelay = (delay) => {
  const [shouldAnimate, setShouldAnimate] = useState(false);
  useEffect(() => {
    const timer = setTimeout(() => setShouldAnimate(true), delay);
    return () => clearTimeout(timer);
  }, [delay]);
  return shouldAnimate;
};

const Hero = ({
  title,
  subtitle,
  primaryButtonText,
  primaryButtonAction,
  style = {},
  announcement = { text: "New feature just arrived", isVisible: false }
}) => {
  // Animation states
  const buttonsReady = useAnimationDelay(600);
  const subtitleReady = useAnimationDelay(400);
  const titleReady = useAnimationDelay(200);

  // Button click handler
  const handleButtonClick = (action) => {
    typeof action === 'function' ? action() : window.open(action, '_blank', 'noopener noreferrer');
  };

  return (
    <section className="hero" style={style}>
      <div className="hero__wrapper">
      <div className="hero__content" >
        {announcement.isVisible && (
          <div className="hero__announcement">
            <button className="announcement-cta">
              New
              <svg viewBox="0 0 24 24" height="15" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path fillRule="evenodd" clipRule="evenodd" d="M17.6492 11.2501L12.7904 6.53852L13.8346 5.46167L20.5774 12.0001L13.8346 18.5385L12.7904 17.4617L17.6492 12.7501H3V11.2501H17.6492Z" fill="currentColor"/>
              </svg>
            </button>
            <span className="announcement-text">{announcement.text}</span>
            
          </div>
        )}

        <div style={{position:"relative"}}>
        <div className="text-overlay"></div>
        <div className="text-overlay2"></div>
          <h1 className={`hero__title ${titleReady ? 'hero__title--animate' : ''}`}>
            {title}
          </h1>
          
        </div>

        <p className={`hero__subtitle ${subtitleReady ? 'hero__subtitle--animate' : ''}`}>
          {subtitle}
        </p>
      </div>

      <div className={`hero__buttons ${buttonsReady ? 'hero__buttons--animate' : ''}`}>
        <button 
          onClick={() => handleButtonClick(primaryButtonAction)}
          className="hero__button hero__button--primary"
        >
          {primaryButtonText}
        </button>
        <button 
          className="hero__button hero__button--secondary"
        >
          Customer requests
        </button>
      </div>
      <div style={{display:"flex", gap:"20px", flexWrap:"wrap", marginTop:"70px"}}>
          <div className='hero-avatar-div' style={{flex:"1", minWidth:"350px", display:"flex", flexDirection:"column", justifyContent:"flex-end", gap:"20px"}}>
            <MultiAvatars
              numPeople={56}
              avatarUrls={["https://plus.unsplash.com/premium_photo-1664541336896-b3d5f7dec9a3?q=80&w=1887&auto=format&fit=crop&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D","https://images.unsplash.com/photo-1438761681033-6461ffad8d80?q=80&w=2070&auto=format&fit=crop&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D","https://images.unsplash.com/photo-1624561172888-ac93c696e10c?q=80&w=1889&auto=format&fit=crop&ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D","https://avatars.githubusercontent.com/u/59228569?v=4"]}
              avatarSize={"45px"}
              avatarBorderWidth={"2px"}
              avatarBorderColor={"rgba(0, 0, 0, 1)"}
              avatarRightShift={"11px"}
              showNumbersDiv={false}
              numbersDivBackground={"#000000"}
              numbersDivFontColor={"rgba(255, 255, 255, 0.2573167754382622)"}
              numbersDivFontSize={"12px"}
              numbersDivFontWeight={550}
              onNumbersDivClick={()=>{}}
            />
            <div className='hero-avatar-div-text' style={{fontSize:"15px", lineHeight:"24px", color:"var(--text-secondary)", marginBottom:"10px", fontWeight:"200"}}>
              Loved by over 100 businesses and customers around the globe, we’ve built a solid reputation!
            </div>
          </div>
          <GlowCard
            width={"350px"}
            height={"200px"}
            showBorder={true}
            borderColor={"rgba(255,255,255,0.1)"}
            borderWidth={"1px"}
            borderRadius={"24px"}
            glowHorizontal={"195px"}
            glowVertical={"180px"}
            glowHeight={"200px"}
            glowWidth={"495px"}
            blurFilter={"79px"}
            glowColor1={"rgba(255, 128, 18, 0.8)"}
            glowColor2={"rgba(0,0,0, 1)"}
            style={{flex:"1", minWidth:"260px", background: "rgba(0,0,0, 0.2)", backdropFilter: "blur(10px)"}}
            content={
              <div style={{width:"100%", height:"100%", display:"flex", flexDirection:"column", justifyContent:"center", gap:"30px"}}>
                <div style={{display:"flex", justifyContent:"center", opacity:"0.6"}}>{svg1}</div>
                <div style={{marginLeft:"40px", fontSize:"18px", fontWeight:"500", color:"var(--text-secondary)", opacity:"0.6"}}>Crafted to Perfection</div>
              </div>
            }
          />
          <GlowCard
            width={"350px"}
            height={"200px"}
            showBorder={true}
            borderColor={"rgba(255,255,255,0.1)"}
            borderWidth={"1px"}
            borderRadius={"24px"}
            glowHorizontal={"195px"}
            glowVertical={"180px"}
            glowHeight={"200px"}
            glowWidth={"495px"}
            blurFilter={"79px"}
            glowColor1={"rgba(0, 0, 0, 1)"}
            glowColor2={"rgba(255, 128, 18, 0.8)"}
            style={{flex:"1", minWidth:"260px", background: "rgba(0,0,0, 0.2)", backdropFilter: "blur(10px)"}}
            content={
              <div style={{width:"100%", height:"100%", display:"flex", flexDirection:"column", justifyContent:"center", gap:"30px"}}>
                <div style={{display:"flex", justifyContent:"center", opacity:"0.6"}}>{svg2}</div>
                <div style={{marginLeft:"40px", fontSize:"18px", fontWeight:"500", color:"var(--text-secondary)", opacity:"0.6"}}>Designed to be Fast</div>
              </div>
            }
          />
      </div>
      </div>
      
    </section>
  );
};





