import React, { memo } from 'react';
import './SectionHeaders.css';

const SectionHeaders = ({
  title,
  subtitle,
  bannerLogo,
  style = {},
  titleClassName = '',
  subtitleClassName = '',
  bannerClassName = '',
  onBannerClick
}) => {

  const Title = () => (
    <h2 className={`section-headers__title ${titleClassName}`}>
      {title}
      <div className='section-headers__title__gradient'></div>
    </h2>
  );

  const Subtitle = () => (
    <p className={`section-headers__subtitle ${subtitleClassName}`}>
      {subtitle}
    </p>
  );

  return (
    <section className="section-headers" style={style}>
      <div className="section-headers__content">
        {title && <Title />}
        {subtitle && <Subtitle />}
      </div>
    </section>
  );
};

export default memo(SectionHeaders);