import React from 'react';
import './Features.css';



const FEATURES_DATA = [
  {
    style: { flex: '1.6' },
    title: 'Built for your keyboard',
    description: 'Fly through your tasks with rapid-fire keyboard shortcuts for everything. Literally everything.',
    image: 'https://i.ibb.co/1L8Mz4v/SVG.png'
  },
  {
    style: { flex: '1' },
    title: 'Breathtakingly fast',
    description: 'Built for speed with 50ms interactions and real-time sync.',
    image: 'https://i.ibb.co/6rBd6wR/Group-1.png'
  },
  {
    style: { flex: '1' },
    title: 'Designed for modern software teams',
    description: 'Comes with built-in workflows that create focus and routine.',
    image: 'https://i.ibb.co/sbWz0H0/SVG-1.png'
  },
  {
    style: { flex: '1.6' },
    title: 'Meet your command line',
    description: 'Complete any action in seconds with the global command menu.',
    image: 'https://i.ibb.co/6Wdp4Xb/Container.png'
  }
]

function Feature({ style, title, description, image }) {
  return (
    <div style={style} className="feature-div">
      <div className="feature-content">
        <div 
          className="image-container"
          style={{
            flex: 1,
            margin: '40px',
            marginBottom: 0,
            overflow: 'hidden',
            display: 'flex',
            alignItems: 'center',
            position: 'relative',
            backgroundImage: `url(${image})`,
            backgroundSize: 'contain',
            backgroundPosition: 'center top',
            backgroundRepeat: 'no-repeat'
          }}
        />
        <div className="text-container">
          <h3 className="title">{title}</h3>
          <p className="description">{description}</p>
        </div>
      </div>
    </div>
  );
}

function Features() {
  const [firstRow, secondRow] = [
    FEATURES_DATA.slice(0, 2),
    FEATURES_DATA.slice(2)
  ];

  return (
    <div className="features-main-div">
      <div className="gradient-overlay" />
      {[firstRow, secondRow].map((row, index) => (
        <div key={index} style={{display: 'flex', flexWrap: 'wrap', gap: '20px'}}>
          {row.map((feature, featureIndex) => (
            <Feature 
              key={`${index}-${featureIndex}`}
              {...feature}
            />
          ))}
        </div>
      ))}
    </div>
  );
}

export default Features;