import React, { ReactNode } from 'react';
import './Navigation.css';

const defaultData = [
  {
    title: "Features",
    link: "/"
  },{
    title: "Company",
    link: "/"
  },
  {
    title: "Developers",
    link: "/"
  },
  {
    title: "Changelog",
    link: "/"
  }
];

const Navigation = ({
  data = defaultData,
  fontSize = "var(--font-size)",
  fontColor = "var(--text-primary)",
  fontWeight = 500,
  horizontalPadding = "14px",
  verticalPadding = "13px",
  borderRadius = "4px",
  gap = "8px",
  iconSize = "10px",
  backgroundColor = "var(--theme-background)",
  hoverBgColor = "var(--bg-banner)",
  contentDivWidth = "115%",
  showContentBorder = true,
  contentBorderRadius = "8px",
  contentBorderColor = "var(--border-color)",
  contentTopMargin = "8px"
}) => {
  const handleMouseEnter = (event) => {
    const contentSubDiv = event.currentTarget.querySelector('.content-sub-div');
    if (!contentSubDiv) return;

    const boundaryThickness = 8;
    const bounds = event.currentTarget.getBoundingClientRect();
    const x = event.clientX - bounds.left;
    const y = event.clientY - bounds.top;

    let transformValue = '';

    if (x <= boundaryThickness) {
      transformValue = 'opacity(1)';
    } else if (x >= bounds.width - boundaryThickness) {
      transformValue = 'opacity(1)';
    } else if (y <= boundaryThickness) {
      transformValue = 'opacity(1)';
    } else if (y >= bounds.height - boundaryThickness) {
      transformValue = 'opacity(1)';
    }

    contentSubDiv.style.transition = 'none';
    requestAnimationFrame(() => {
      contentSubDiv.style.transform = transformValue;
      requestAnimationFrame(() => {
        contentSubDiv.style.transition = 'transform 0.2s ease-in-out';
        contentSubDiv.style.transform = 'opacity(0)';
      });
    });
  };

  const ChevronIcon = () => (
    <svg 
      height={iconSize} 
      width={iconSize} 
      viewBox="0 0 24 24" 
      fill="none" 
      xmlns="http://www.w3.org/2000/svg"
      className="nav-chevron"
    >
      <path 
        d="M20 16L12 8L4 16" 
        stroke={fontColor} 
        strokeWidth="2" 
        strokeLinecap="round" 
        strokeLinejoin="round"
      />
    </svg>
  );

  return (
    <nav 
      className="navigation-container"
      style={{
        '--nav-font-size': fontSize,
        '--nav-font-color': fontColor,
        '--nav-font-weight': fontWeight,
        '--nav-h-padding': horizontalPadding,
        '--nav-v-padding': verticalPadding,
        '--nav-border-radius': borderRadius,
        '--nav-gap': gap,
        '--nav-bg-color': backgroundColor,
        '--nav-hover-bg-color': hoverBgColor,
        '--nav-content-width': contentDivWidth,
        '--nav-content-border-radius': contentBorderRadius,
        '--nav-content-border-color': contentBorderColor,
        '--nav-content-top-margin': contentTopMargin,
      }}
    >
      {data.map((item, index) => (
        item.link ? (
          <a 
            key={index}
            href={item.link} 
            className="navigation-button"
          >
            {item.title}
          </a>
        ) : (
          <div 
            key={index}
            className="navigation-button"
          >
            {item.title}
          </div>
        )
      ))}
    </nav>
  );
};

export default Navigation;