import React, { ReactNode, CSSProperties } from 'react';

const GlowCard = ({
  width = "450px",
  height = "200px",
  backgroundColor = "#000000",
  showBorder = true,
  borderColor = "#212225",
  borderWidth = "1px",
  borderRadius = "24px",
  glowHorizontal = "150px",
  glowVertical = "100px",
  glowHeight = "200px",
  glowWidth = "300px",
  blurFilter = "70px",
  glowColor1 = "rgb(255,69,51)",
  glowColor2 = "rgba(0,102,255,1)",
  content = (
    <div
      style={{
        height: "100%",
        width: "100%",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        color: "#ffffff",
        fontSize: "22px",
        fontWeight: "600",
      }}
    >
      Heliocrafts
    </div>
  ),
  style={}
}) => {
  const styles = {
    mainContainer: {
      width,
      height,
      position: "relative",
      overflow: "hidden",
      borderRadius,
      border: showBorder ? `${borderWidth} solid ${borderColor}` : "none",
      backgroundColor,
      ...style
    },
    glowTopLeft: {
      position: "absolute",
      top: `calc(-1 * ${glowVertical})`,
      left: `calc(-1 * ${glowHorizontal})`,
      width: glowWidth,
      height: glowHeight,
      borderRadius: "100%",
      background: `radial-gradient(circle at center, ${glowColor1} 30%, rgba(255,0,0,0) 70%)`,
      filter: `blur(${blurFilter})`,
      opacity: 1,
      zIndex: 0,
    },
    glowBottomRight: {
      position: "absolute",
      bottom: `calc(-1 * ${glowVertical})`,
      right: `calc(-1 * ${glowHorizontal})`,
      width: glowWidth,
      height: glowHeight,
      borderRadius: "100%",
      background: `radial-gradient(circle at center, ${glowColor2} 30%, rgba(0,102,255,0) 70%)`,
      filter: `blur(${blurFilter})`,
      opacity: 1,
      zIndex: 0,
    },
    contentWrapper: {
      height: "100%",
      width: "100%",
      position: "relative",
      zIndex: 1,
    },
  };

  return (
    <div style={styles.mainContainer}>
      <div style={styles.glowTopLeft}></div>
      <div style={styles.glowBottomRight}></div>
      <div style={styles.contentWrapper}>{content}</div>
    </div>
  );
};

export default GlowCard;
