import React from 'react';
import './IllustrationSection.css';


const FEATURES_DATA = [
    {
        title: 'Multi-team projects.',
        description: 'Collaborate across teams and departments across your company.'
    },
    {
        title: 'Project documents.',
        description: 'Write project briefs and specs directly in Linear for easy access.'
    },
    {
        title: 'Custom roadmaps.',
        description: 'Organize projects across multiple roadmaps for better visibility.'
    },
    {
        title: 'Timeline view.',
        description: 'Visualize the product journey ahead and plan accordingly for success.'
    },
    {
        title: 'Project insights.',
        description: 'Track scope, velocity, and progress over time with project insights.'
    },
    {
        title: 'Personal notifications.',
        description: 'Stay in the loop on project activity and updates with personal notifications.'
    }
]

const IllustrationSection = ({
        imageSource = "https://i.ibb.co/m675wtt/f-auto-q-95-fit-scale-down-metadata-none-11.png",
        list = FEATURES_DATA
}) => (
    <div className="illustrations-main-div">
        <div className="gradient-overlay" />
        <div className="illustration-container">
            <img 
                src={imageSource} 
                alt="Timeline illustration"
                className="illustration-image" 
            />
            <div className="fade-overlay" />
        </div>
        <div className="features-grid">
            {list.map((feature, index) => (
                <div key={index} className="feature-item">
                    <h3>{feature.title}</h3>
                    <p>{feature.description}</p>
                </div>
            ))}
        </div>
    </div>
);

export default IllustrationSection;