import React from 'react';
import './FeaturesSection.css';

const SECTIONS_DATA = [
  {
    title: 'List and board',
    description: 'Switch between list and board layout to view work from any angle.',
    image: 'https://i.ibb.co/MhK3qwL/f-auto-q-95-fit-scale-down-metadata-none-5.png'
  },
  {
    title: 'Make it yours',
    description: 'Quickly apply filters and operators to refine your issue lists and create custom views.',
    image: 'https://i.ibb.co/PhC292X/f-auto-q-95-fit-scale-down-metadata-none-9.png'
  },
  {
    title: 'Project updates',
    description: 'Keep everyone up-to-date on the health and progress of projects.',
    image: 'https://i.ibb.co/Rcpd2FF/f-auto-q-95-fit-scale-down-metadata-none-8.png'
  },
  {
    title: 'Focus on the big picture',
    description: 'Explore every company project in one view to easily identify what needs attention.',
    image: 'https://i.ibb.co/pzbkH8m/f-auto-q-95-fit-scale-down-metadata-none-6.png'
  }
]

const Feature = ({ style, image }) => (
  <div style={style} className="feature-section-div">
    <div className="feature-section-content">
      <div className="feature-image" style={{ backgroundImage: `url(${image})` }} />
    </div>
  </div>
);

const FeatureTextContent = ({ title, description }) => (
  <div className="feature-text-container">
    <h2 className="feature-title">{title}</h2>
    <p className="feature-description">{description}</p>
    <button className="feature-section-button">Book your demo</button>
  </div>
);

const FeaturesSection = () => (
  <div className="features-section-main-div">
    <div className="gradient-overlay" />
    {SECTIONS_DATA.map((section, index) => (
      <div key={index} className="feature-row">
        <FeatureTextContent title={section.title} description={section.description} />
        <Feature style={{ flex: '1' }} image={section.image} />
      </div>
    ))}
  </div>
);

export default FeaturesSection;